package com.fab.server;

import com.fab.util.HttpUtil;
import com.fab.util.SessionManager;
import com.sun.net.httpserver.HttpExchange;
import com.sun.net.httpserver.HttpHandler;

import java.io.*;
import java.nio.file.*;

/**
 * Serves chart images generated by Python from web/charts/
 */
public class ChartHandler implements HttpHandler {
    private static final String CHARTS_DIR = "D:/project-fab/web/charts";

    @Override
    public void handle(HttpExchange ex) throws IOException {
        if ("OPTIONS".equals(ex.getRequestMethod())) { HttpUtil.sendOptions(ex); return; }
        if (!SessionManager.isValid(SessionManager.extractToken(ex))) {
            HttpUtil.sendJson(ex, 401, "{\"error\":\"Unauthorized\"}"); return;
        }
        String path = ex.getRequestURI().getPath(); // /api/charts/{filename}
        String[] parts = path.split("/");
        if (parts.length < 4) { HttpUtil.sendJson(ex, 400, "{\"error\":\"Chart name required\"}"); return; }
        String filename = parts[3];
        if (filename.contains("..")) { HttpUtil.sendJson(ex, 403, "{\"error\":\"Forbidden\"}"); return; }
        File file = new File(CHARTS_DIR + "/" + filename);
        if (!file.exists()) { HttpUtil.sendJson(ex, 404, "{\"error\":\"Chart not found\"}"); return; }
        byte[] bytes = Files.readAllBytes(file.toPath());
        HttpUtil.sendFile(ex, 200, bytes, "image/png");
    }
}
